            if (op.equals("put")) {
                int id = Integer.parseInt(st.nextToken());
                system.put(id, st.nextToken());
            } else {
                String s = st.nextToken(), e = st.nextToken(), g = st.nextToken();
                List<Integer> ids = new ArrayList<>(system.retrieve(s, e, g));
                Collections.sort(ids);
                if (ids.isEmpty()) out.append("-1");
                for (int j = 0; j < ids.size(); j++) out.append(j > 0 ? " " : "").append(ids.get(j));
                out.append("\n");
            }
        }
        System.out.print(out);
    }
